mapper.select:
SELECT

FROM FLOW_TASK ft
LEFT JOIN FLOW_DEFINITION fd ON ft.DEFINITION_ID=fd.ID
LEFT JOIN FLOW_INSTANCE fi ON ft.INSTANCE_ID=fi.ID
LEFT JOIN FLOW_USER fu ON fu.ASSOCIATED = ft.ID

    AND fu.processed_by = #{p.processedBy}


        AND ft.DEFINITION_ID = #{p.definitionId}


        AND ft.INSTANCE_ID = #{p.instanceId}


        AND ft.NODE_CODE = #{p.nodeCode}


        AND ft.NODE_NAME = #{p.nodeName}


        AND ft.NODE_TYPE = #{p.nodeType}


        AND ft.FLOW_STATUS = #{p.flowStatus}


        AND ft.FORM_CUSTOM = #{p.formCustom}


        AND ft.FORM_PATH = #{p.formPath}


        AND ft.DEL_FLAG = #{p.delFlag}


        AND ft.TENANT_ID = #{p.tenantId}


        AND ft.ID = #{p.id}


        AND ft.CREATE_TIME = #{p.createTime}


        AND ft.CREATE_BY = #{p.createBy}


        AND ft.UPDATE_TIME = #{p.updateTime}


        AND ft.UPDATE_BY = #{p.updateBy}



        AND fd.FLOW_NAME like CONCAT('%',#{p.flowName},'%')


        AND fi.BUSINESS_ID = #{p.businessId}


ORDER BY ft.CREATE_TIME ASC
